import math
from collections import deque


def cluster_points(points, *, radius, min_size, bounds=None):
    if not isinstance(radius, (int, float)) or isinstance(radius, bool) or not math.isfinite(radius) or radius <= 0:
        raise ValueError('radius must be positive and finite')
    if not isinstance(min_size, int) or isinstance(min_size, bool) or min_size < 1:
        raise ValueError('min_size must be a positive integer')
    checked_bounds = None
    if bounds is not None:
        try:
            if len(bounds) != 3:
                raise ValueError
            checked_bounds = []
            for pair in bounds:
                if len(pair) != 2:
                    raise ValueError
                lo, hi = pair
                if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) for v in pair) or lo > hi:
                    raise ValueError
                checked_bounds.append((float(lo), float(hi)))
        except (TypeError, ValueError):
            raise ValueError('invalid bounds') from None
    clean = []
    try:
        iterator = iter(points)
    except TypeError:
        raise ValueError('points must be iterable') from None
    for point in iterator:
        try:
            if len(point) != 3:
                raise ValueError
            if any(isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v) for v in point):
                raise ValueError
            item = tuple(float(v) for v in point)
        except (TypeError, ValueError):
            raise ValueError('invalid point') from None
        if checked_bounds is None or all(lo <= item[i] <= hi for i, (lo, hi) in enumerate(checked_bounds)):
            clean.append(item)
    limit = float(radius) ** 2
    neighborhoods = [[j for j, q in enumerate(clean) if sum((a - b) ** 2 for a, b in zip(p, q)) < limit] for p in clean]
    labels = [None] * len(clean)
    clusters = []
    for start in range(len(clean)):
        if labels[start] is not None:
            continue
        if len(neighborhoods[start]) < min_size:
            labels[start] = -1
            continue
        label = len(clusters)
        labels[start] = label
        queue = deque(neighborhoods[start])
        queued = set(neighborhoods[start])
        while queue:
            index = queue.popleft()
            if labels[index] == -1:
                labels[index] = label
            if labels[index] is not None:
                continue
            labels[index] = label
            if len(neighborhoods[index]) >= min_size:
                for neighbor in neighborhoods[index]:
                    if neighbor not in queued:
                        queued.add(neighbor)
                        queue.append(neighbor)
        clusters.append([tuple(clean[i]) for i, value in enumerate(labels) if value == label])
    noise = [tuple(clean[i]) for i, value in enumerate(labels) if value == -1]
    return {'clusters': clusters, 'noise': noise}

